    ('act14side/level_act14side_st01_nep0num.csv', 'line-133', 'Передай Гуро, пусть сначала «пригласит» почетного гостя Энсиодеса к нам, а потом мы решим, что делать дальше.', 'Передай Гуло, пусть сначала «пригласит» почетного гостя Энсиодеса к нам, а потом мы решим, что делать дальше.'),
    ('act14side/level_act14side_st01_nep0num.csv', 'line-190', 'Полгода назад генерал Гуро из дома Пельрочи даже вступил из-за этого в конфликт с Носисом.', 'Полгода назад генерал Гуло из дома Пельрочи даже вступил из-за этого в конфликт с Носисом.'),
