    ('act14side/level_act14side_st03_nep0num.csv', 'line-1206', 'Леди Шулис, скорее!', 'Леди Шюрюс, скорее!'),
    ('act14side/level_act14side_st03_nep0num.csv', 'line-1250', 'Господин, у людей Энсиодиса большое преимущество, нас подавляют!', 'Господин, у людей Энсиодеса большое преимущество, нас подавляют!'),
